const state={status:'Offline play is optional. Preparing it downloads this build’s local code, artwork, fonts and player models.',storage:'Storage usage is being checked.',busy:false,error:false,ready:false,waiting:false};let registration,installed=false,callbacks;
export function offlinePanel(){return `<section class="offline-panel"><h3>Install & offline play</h3><p data-offline-status role="status"></p><p data-offline-storage role="status"></p><div class="save-controls" style="flex-wrap:wrap"><button class="btn secondary" data-offline-action="prepare">Prepare offline play</button><button class="btn secondary" data-offline-action="check">Check for app update</button><button class="btn primary" data-offline-action="apply" hidden>Use prepared build</button><button class="btn secondary" data-offline-action="cleanup">Clean up old builds</button><button class="btn ghost" data-offline-action="remove">Remove offline files</button></div><p>Updates wait until you choose to use them. Finish active matches and simulations first. A save recovery copy is made before switching builds. Old builds are cleaned up when one Touchline tab is open. The current build, one rollback build and any pending download are retained. Removing offline files leaves saves and replays intact. Your browser’s install option can add Touchline to your device.</p></section>`;}
function refresh(){for(const node of document.querySelectorAll('[data-offline-status]'))node.textContent=state.status;for(const node of document.querySelectorAll('[data-offline-storage]'))node.textContent=state.storage;for(const button of document.querySelectorAll('[data-offline-action]')){button.disabled=state.busy;button.hidden=button.dataset.offlineAction==='apply'&&!state.ready&&!state.waiting;}}
function workerRequest(type){return new Promise((resolve,reject)=>{const worker=navigator.serviceWorker.controller||registration?.active;if(!worker)return reject(Error('Prepare and use an offline build first.'));const channel=new MessageChannel(),timer=setTimeout(()=>{channel.port1.close();reject(Error('The installed worker did not answer. Use the prepared build and try again.'));},10000);channel.port1.onmessage=e=>{clearTimeout(timer);channel.port1.close();e.data?.ok?resolve(e.data):reject(Error(e.data?.error||'Offline storage request failed.'));};worker.postMessage({type},[channel.port2]);});}
async function storageUsage(result){let estimate;try{estimate=await navigator.storage?.estimate();}catch{}const mb=n=>(n/1e6).toFixed(1)+' MB';state.storage=(result?`${result.builds} offline build${result.builds===1?'':'s'} · ${mb(result.bytes)} verified asset bytes. `:'')+(estimate?`Browser estimate: ${mb(estimate.usage||0)} used of ${mb(estimate.quota||0)} for this site, including saves.`:'Browser storage estimate is unavailable.');refresh();}
async function prepareCurrentBuild(){const response=await fetch('./offline-manifest.json',{cache:'no-store'});if(!response.ok)throw Error('The offline build manifest is unavailable.');const manifest=await response.json();if(typeof manifest.version!=='string'||!/^[-a-zA-Z0-9.]+$/.test(manifest.version)||!/^[a-f0-9]{20}$/.test(manifest.id))throw Error('Invalid offline build metadata.');const reg=await navigator.serviceWorker.register(`./service-worker.js?build=${encodeURIComponent(manifest.version)}&id=${manifest.id}`,{type:'module',updateViaCache:'none'});watch(reg);reg.__watched=true;return reg;}
function watch(reg){registration=reg;state.waiting=!!reg.waiting;state.ready=reg.active?.state==='activated';const observe=worker=>worker?.addEventListener('statechange',()=>{if(worker.state==='installed'||worker.state==='activated'){state.waiting=!!reg.waiting;state.ready=reg.active?.state==='activated'||worker.state==='activated';state.busy=false;state.status='Build prepared. Use prepared build when you are ready; existing progress is preserved.';refresh();}else if(worker.state==='redundant'){state.busy=false;if(!state.error)state.status='Offline preparation did not complete. The previous installed build and saves are retained.';refresh();}});observe(reg.installing);reg.addEventListener('updatefound',()=>observe(reg.installing));}
export function installOffline(options){
 if(installed)return;installed=true;callbacks=options;
 new MutationObserver(refresh).observe(document.getElementById('modal'),{childList:true});
 navigator.serviceWorker?.addEventListener('message',e=>{if(e.data?.type!=='TOUCHLINE_OFFLINE')return;state.status=e.data.message;if(e.data.error){state.error=true;state.busy=false;}refresh();});
 let switching=false;navigator.serviceWorker?.addEventListener('controllerchange',()=>{if(switching)location.reload();});
 storageUsage();navigator.serviceWorker?.getRegistration('./').then(async reg=>{if(!reg)return;watch(reg);reg.__watched=true;state.status=reg.waiting?'An update is waiting. Your installed build and saves remain in use.':'An offline build is installed on this device.';refresh();if(navigator.serviceWorker.controller){try{await storageUsage(await workerRequest('TOUCHLINE_CLEANUP'));}catch{try{await storageUsage(await workerRequest('TOUCHLINE_STORAGE'));}catch{}}}}).catch(()=>{});
 document.addEventListener('click',async e=>{const button=e.target.closest('[data-offline-action]');if(!button||state.busy)return;const action=button.dataset.offlineAction;
  try{
   if(!('serviceWorker' in navigator)||!isSecureContext)throw Error('This browser needs a secure origin or localhost for offline play.');
   state.busy=true;state.error=false;if(['cleanup','remove'].includes(action))state.status='Checking offline builds and open tabs…';refresh();
   registration||=await navigator.serviceWorker.getRegistration('./');if(registration&&!registration.__watched){watch(registration);registration.__watched=true;}
   if(action==='prepare'){
    if(!navigator.onLine)throw Error('Connect to download the offline build.');state.status='Downloading and verifying the offline build…';refresh();
    registration=await prepareCurrentBuild();
    if(registration.waiting||registration.active&&!registration.installing){state.busy=false;state.waiting=!!registration.waiting;state.ready=registration.active?.state==='activated';state.status='Build is ready. Use prepared build to reload safely.';}
   }else if(action==='check'){
    if(!registration)throw Error('Prepare offline play first.');registration=await prepareCurrentBuild();state.busy=!!registration.installing;state.waiting=!!registration.waiting;state.ready=registration.active?.state==='activated';state.status=state.waiting?'An updated build is ready. Your current game keeps running until you switch.':registration.installing?'Checking and verifying the updated build…':'No downloaded update is waiting. You can keep playing.';
   }else if(action==='apply'){
    if(!registration?.active&&!registration?.waiting)throw Error('Prepare offline play first.');if(!callbacks.canUpdate())throw Error('Finish saved fixtures and stop active play or season simulation before switching builds.');await callbacks.beforeUpdate();
    if(registration.waiting){switching=true;registration.waiting.postMessage({type:'TOUCHLINE_ACTIVATE'});state.status='Waiting to switch. Close other Touchline tabs if the update cannot activate.';state.busy=false;}else location.reload();
   }else if(action==='cleanup'){
    const result=await workerRequest('TOUCHLINE_CLEANUP');await storageUsage(result);state.status=`Removed ${result.removed} old or incomplete build${result.removed===1?'':'s'}. The current build, rollback build and pending update are retained.`;state.busy=false;
   }else if(action==='remove'){
    if(!navigator.onLine)throw Error('Connect before removing offline files so the app can reload.');if(!callbacks.canUpdate())throw Error('Finish active play and pending fixtures before removing offline files.');if((await workerRequest('TOUCHLINE_STORAGE')).windows!==1)throw Error('Close other Touchline tabs before cleaning or removing offline builds.');await callbacks.beforeUpdate();await workerRequest('TOUCHLINE_REMOVE');location.reload();
   }
  }catch(error){state.busy=false;const current=await navigator.serviceWorker?.getRegistration('./').catch(()=>null);if(current){registration=current;state.waiting=!!current.waiting;state.ready=current.active?.state==='activated';}state.error=true;state.status=error.message;refresh();}refresh();
 });
}
